&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;맑은 고딕,Segoe UI&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;본고지는 『채용절차의공정화에관한법률』제&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;11조제6항에&amp;nbsp;따른 것&amp;nbsp;입니다.&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;  &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; &lt;/span&gt; &lt;/li&gt;
